    createdByName: fullName(state.user),
    createdByRole: state.user.role,
    createdAt: now,
    updatedAt: now,
    driverId: child.driverId || childDriver(child)?.id || "",
    driverIds: driverIdsFromRecord(child),
    assistantId: child.assistantId || childAssistant(child)?.id || "",
